import { ChangeDetectionStrategy, Component, computed, ElementRef, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import type { ScrollArea } from './scrollarea';
import type { ScrollAreaScrollbar } from './scrollarea-scrollbar';
import { SCROLLAREA_INSTANCE, SCROLLAREA_SCROLLBAR_INSTANCE } from './scrollarea-token';
import { ScrollAreaStyle } from './style/scrollareastyle';

/**
 * ScrollAreaHandle is a helper component for ScrollArea component.
 * @group Components
 */
@Component({
    selector: 'p-scrollarea-handle, p-scroll-area-handle',
    standalone: true,
    imports: [BindModule],
    template: ``,
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [{ provide: PARENT_INSTANCE, useExisting: ScrollAreaHandle }],
    host: {
        '[class]': 'cx("handle")',
        '[attr.data-orientation]': 'orientation()',
        '[style.height]': 'handleHeight()',
        '[style.width]': 'handleWidth()',
        '[style.transform]': 'handleTransform()',
        '(pointerdown)': 'pcScrollArea.onHandlePointerDown($event, orientation())'
    },
    hostDirectives: [Bind]
})
export class ScrollAreaHandle extends BaseComponent {
    componentName = 'ScrollAreaHandle';

    bindDirectiveInstance = inject(Bind, { self: true });

    pcScrollArea = inject<ScrollArea>(SCROLLAREA_INSTANCE);

    pcScrollbar = inject<ScrollAreaScrollbar>(SCROLLAREA_SCROLLBAR_INSTANCE);

    _componentStyle = inject(ScrollAreaStyle);

    private hostEl = inject(ElementRef);

    orientation = computed(() => this.pcScrollbar.orientation());

    isVertical = computed(() => this.orientation() === 'vertical');

    handleHeight = computed(() => (this.isVertical() ? 'var(--px-handle-height, 0px)' : undefined));

    handleWidth = computed(() => (this.isVertical() ? undefined : 'var(--px-handle-width, 0px)'));

    handleTransform = computed(() => (this.isVertical() ? 'translate3d(0, var(--px-handle-offset, 0px), 0)' : 'translate3d(var(--px-handle-offset, 0px), 0, 0)'));

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.pcScrollArea.ptms(['handle']));
    }

    onAfterViewInit() {
        const el = this.hostEl.nativeElement;

        if (this.isVertical()) {
            this.pcScrollArea.handleYEl = el;
        } else {
            this.pcScrollArea.handleXEl = el;
        }
    }
}
