import { ChangeDetectionStrategy, Component, computed, ElementRef, inject, input, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import type { ScrollArea } from './scrollarea';
import { SCROLLAREA_INSTANCE, SCROLLAREA_SCROLLBAR_INSTANCE } from './scrollarea-token';
import { ScrollAreaStyle } from './style/scrollareastyle';

/**
 * ScrollAreaScrollbar is a helper component for ScrollArea component.
 * @group Components
 */
@Component({
    selector: 'p-scrollarea-scrollbar, p-scroll-area-scrollbar',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content></ng-content>`,
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [
        { provide: SCROLLAREA_SCROLLBAR_INSTANCE, useExisting: ScrollAreaScrollbar },
        { provide: PARENT_INSTANCE, useExisting: ScrollAreaScrollbar }
    ],
    host: {
        '[class]': 'cx("scrollbar")',
        '[style]': 'sx("scrollbar")',
        '[attr.data-orientation]': 'orientation()',
        '[attr.data-hovering]': 'dataHovering()',
        '[attr.data-scrolling]': 'dataScrolling()',
        '(pointerdown)': 'pcScrollArea.onScrollbarPointerDown($event, orientation())',
        '(pointermove)': 'pcScrollArea.onScrollbarPointerMove($event)',
        '(pointerup)': 'pcScrollArea.onScrollbarPointerUp($event)',
        '(wheel)': 'pcScrollArea.onScrollbarWheel($event, orientation())'
    },
    hostDirectives: [Bind]
})
export class ScrollAreaScrollbar extends BaseComponent {
    componentName = 'ScrollAreaScrollbar';

    $pcScrollAreaScrollbar: ScrollAreaScrollbar | undefined = inject(SCROLLAREA_SCROLLBAR_INSTANCE, { optional: true, skipSelf: true }) ?? undefined;

    bindDirectiveInstance = inject(Bind, { self: true });

    pcScrollArea = inject<ScrollArea>(SCROLLAREA_INSTANCE);

    _componentStyle = inject(ScrollAreaStyle);

    private hostEl = inject(ElementRef);

    /**
     * Orientation of the scrollbar.
     * @group Props
     */
    orientation = input<'vertical' | 'horizontal'>('vertical');

    isVertical = computed(() => this.orientation() === 'vertical');

    isHidden = computed(() => (this.isVertical() ? this.pcScrollArea.hiddenY() : this.pcScrollArea.hiddenX()));

    dataHovering = computed(() => (this.pcScrollArea.hovering() ? '' : null));

    dataScrolling = computed(() => {
        const isVertical = this.isVertical();

        return (isVertical ? this.pcScrollArea.scrollingY() : this.pcScrollArea.scrollingX()) ? '' : null;
    });

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.pcScrollArea.ptms(['scrollbar']));
    }

    onAfterViewInit() {
        const el = this.hostEl.nativeElement;

        if (this.isVertical()) {
            this.pcScrollArea.scrollbarYEl = el;
        } else {
            this.pcScrollArea.scrollbarXEl = el;
        }
    }
}
