import { ChangeDetectionStrategy, Component, computed, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind, BindModule } from 'primeng/bind';
import type { ScrollArea } from './scrollarea';
import { SCROLLAREA_INSTANCE } from './scrollarea-token';
import { ScrollAreaStyle } from './style/scrollareastyle';

/**
 * ScrollAreaContent is a helper component for ScrollArea component.
 * @group Components
 */
@Component({
    selector: 'p-scrollarea-content, p-scroll-area-content',
    standalone: true,
    imports: [BindModule],
    template: `<ng-content></ng-content>`,
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    providers: [{ provide: PARENT_INSTANCE, useExisting: ScrollAreaContent }],
    host: {
        '[class]': 'cx("content")',
        '[style.min-width]': 'contentMinWidth()',
        '[style.min-height]': 'contentMinHeight()'
    },
    hostDirectives: [Bind]
})
export class ScrollAreaContent extends BaseComponent {
    componentName = 'ScrollAreaContent';

    bindDirectiveInstance = inject(Bind, { self: true });

    pcScrollArea = inject<ScrollArea>(SCROLLAREA_INSTANCE);

    _componentStyle = inject(ScrollAreaStyle);

    contentMinWidth = computed(() => (this.pcScrollArea.hasOverflowX() ? 'fit-content' : null));

    contentMinHeight = computed(() => (this.pcScrollArea.hasOverflowY() ? 'fit-content' : null));

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.pcScrollArea.ptms(['content']));
    }
}
